-- V37__seed_election_runoff_uncertainty_scenario_paths.sql
-- Seeds 472 deterministic asset-path rows for the 2023 election runoff uncertainty scenario.

SET NOCOUNT ON;

DECLARE @Paths TABLE (
    scenario_code VARCHAR(50) NOT NULL,
    asset_code NVARCHAR(50) NOT NULL,
    path_date DATE NOT NULL,
    day_index SMALLINT NOT NULL,
    close_value DECIMAL(20, 8) NOT NULL,
    impact DECIMAL(20, 12) NOT NULL,
    PRIMARY KEY (scenario_code, asset_code, day_index)
);


IF (SELECT COUNT(*) FROM @Paths WHERE scenario_code = 'S12_ELECTION_RUNOFF_UNCERTAINTY_2023') <> 472
BEGIN
    THROW 50071, 'Unexpected path row count for S12_ELECTION_RUNOFF_UNCERTAINTY_2023.', 1;
END;

IF (SELECT COUNT(DISTINCT asset_code) FROM @Paths WHERE scenario_code = 'S12_ELECTION_RUNOFF_UNCERTAINTY_2023') <> 59
BEGIN
    THROW 50072, 'Unexpected asset coverage for S12_ELECTION_RUNOFF_UNCERTAINTY_2023.', 1;
END;

IF (SELECT COUNT(DISTINCT day_index) FROM @Paths WHERE scenario_code = 'S12_ELECTION_RUNOFF_UNCERTAINTY_2023') <> 8
BEGIN
    THROW 50073, 'Unexpected trading-day coverage for S12_ELECTION_RUNOFF_UNCERTAINTY_2023.', 1;
END;

IF (SELECT MIN(day_index) FROM @Paths WHERE scenario_code = 'S12_ELECTION_RUNOFF_UNCERTAINTY_2023') <> 0
   OR (SELECT MAX(day_index) FROM @Paths WHERE scenario_code = 'S12_ELECTION_RUNOFF_UNCERTAINTY_2023') <> 12
BEGIN
    THROW 50074, 'Unexpected path day range for S12_ELECTION_RUNOFF_UNCERTAINTY_2023.', 1;
END;

IF EXISTS (
    SELECT 1
    FROM @Paths p
    LEFT JOIN dbo.assets a ON a.asset_code = p.asset_code
    WHERE a.id IS NULL
)
BEGIN
    THROW 50075, 'Stress path dataset contains an unknown asset.', 1;
END;

UPDATE target
SET
    target.path_date = source.path_date,
    target.close_value = source.close_value,
    target.impact = source.impact
FROM dbo.stress_scenario_asset_paths target
JOIN dbo.stress_scenarios scenario ON scenario.id = target.scenario_id
JOIN dbo.assets asset ON asset.id = target.asset_id
JOIN @Paths source
    ON source.scenario_code = scenario.code
   AND source.asset_code = asset.asset_code
   AND source.day_index = target.day_index;

    scenario_id, asset_id, path_date, day_index, close_value, impact
)
SELECT scenario.id, asset.id, source.path_date, source.day_index, source.close_value, source.impact
FROM @Paths source
JOIN dbo.stress_scenarios scenario ON scenario.code = source.scenario_code
JOIN dbo.assets asset ON asset.asset_code = source.asset_code
WHERE NOT EXISTS (
    SELECT 1
    FROM dbo.stress_scenario_asset_paths existing
    WHERE existing.scenario_id = scenario.id
      AND existing.asset_id = asset.id
      AND existing.day_index = source.day_index
);

IF (
    SELECT COUNT(*)
    FROM dbo.stress_scenario_asset_paths p
    JOIN dbo.stress_scenarios s ON s.id = p.scenario_id
    WHERE s.code = 'S12_ELECTION_RUNOFF_UNCERTAINTY_2023'
) <> 472
BEGIN
    THROW 50076, 'Persisted path coverage is not 472 rows for S12_ELECTION_RUNOFF_UNCERTAINTY_2023.', 1;
END;

SET NOCOUNT OFF;
